insert into public.site_content (id,page,section,field,kind,value,published) values ('34aba71f-e7a0-44fc-afea-e5b7d6ffada2','quem-somos','section-02','text-003','text','às próximas conquistas.',true) on conflict (page,section,field) do nothing;
insert into public.site_content (id,page,section,field,kind,value,published) values ('43faa0a9-f37a-402e-ad68-b69c3c78939c','quem-somos','section-02','text-004','text','A BRASA UH é a Brazilian Student Association at the University of Houston: uma comunidade que aproxima estudantes brasileiros, valoriza nossa cultura e cria conexões que acompanham cada etapa da vida universitária.',true) on conflict (page,section,field) do nothing;
insert into public.site_content (id,page,section,field,kind,value,published) values ('17bd32b7-701a-447d-af22-aa8bf4d61d5c','quem-somos','section-02','text-005','text','Nossa missão é construir um ambiente de acolhimento, colaboração e crescimento. Queremos que cada estudante encontre espaço para compartilhar sua história, desenvolver seu potencial e contribuir com a comunidade.',true) on conflict (page,section,field) do nothing;
insert into public.site_content (id,page,section,field,kind,value,published) values ('cf25af93-9623-48f4-a51d-4973e6b66f89','quem-somos','section-02','text-006','text','Entre uma conversa no campus, um encontro cultural e uma nova oportunidade, fortalecemos os laços entre o Brasil e Houston. Com raízes brasileiras e espírito Cougar, seguimos construindo essa experiência juntos.',true) on conflict (page,section,field) do nothing;
insert into public.site_content (id,page,section,field,kind,value,published) values ('6f805055-9f9f-4b7d-ab1b-186d94ff4949','quem-somos','section-03','text-001','text','O QUE NOS MOVE',true) on conflict (page,section,field) do nothing;
